-- 標籤：就地移除類型性質的標籤，其他標籤原封不動
update public.pois set data = jsonb_set(data, '{tags}', coalesce((select jsonb_agg(t) from jsonb_array_elements(data->'tags') t where (t #>> '{}') <> all (array['美食','餐廳','拉麵','甜點','咖啡','神社','公園','自然景觀','漢堡','壽喜燒','涮涮鍋','連鎖速食','生活雜貨','器物'])), '[]'::jsonb)) where jsonb_typeof(data->'tags') = 'array';

-- 檢查：各都道府縣的筆數、區市數、車站數；仍有類型標籤應為 0
select split_part(data->>'region','／',1) as 都道府縣, count(*) as 筆數, count(distinct split_part(data->>'region','／',2)) as 區市, count(distinct data->>'region') as 車站, (select count(*) from public.pois p2, jsonb_array_elements_text(p2.data->'tags') t where t = any (array['美食','餐廳','拉麵','甜點','咖啡','神社','公園','自然景觀','漢堡','壽喜燒','涮涮鍋','連鎖速食','生活雜貨','器物'])) as 仍有類型標籤 from public.pois group by 1 order by 2 desc;
